{
  "segment_function": "Discussing the distinction between labor and work, the methodological approach toward criticizing Karl Marx, and the historical context of ancient contempt for laboring.",
  "claims": [
    {
      "claim": "The author proposes a distinction between labor and work that is unusual and lacks substantial precedent in the pre-modern tradition of political thought or modern labor theories.",
      "claim_type": "author_position",
      "supporting_excerpt": "The distinction between labor and work which I propose is unusual. The phenomenal evidence in its favor is too striking to be ignored, and yet historically it is a fact that apart from a few scattered remarks, which moreover were never developed even in the theories of their authors, there is hardly anything in either the pre-modern tradition of political thought or in the large body of modern labor theories to support it.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "Every European language contains two etymologically unrelated words for what is commonly considered the same activity and retains them despite persistent synonymous usage.",
      "claim_type": "author_position",
      "supporting_excerpt": "Against this scarcity of historical evidence, however, stands one very articulate and obstinate testimony, namely, the simple fact that every European language, ancient and modern, contains two etymologically unrelated words for what we have to come to think of as the same activity, and retains them in the face of their persistent synonymous usage.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "labor",
      "definition": "A verbal noun to be classed with the gerund that never designates the finished product or the result of laboring."
    }
  ],
  "distinctions": [
    {
      "item_a": "labor",
      "item_b": "work",
      "distinction": "Labor is represented by a verbal noun that never designates a finished product, whereas the product itself is invariably derived from the word for work."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The author's proposed distinction between labor and work.",
    "The etymological persistence of two separate words across European languages."
  ]
}

